SELECT 'gongkao', '增长类排序', 'kp-xingce-data-rank-growth', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "增长类排序"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "区分“率”的排序和“量”的排序。极其容易因为审题不清而导致全军覆没。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题目要求按“增速/增幅”或“增多/减少的绝对量”进行排序。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心判定准则"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "1. 排序增长“率”：", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 直接比较 现期量/基期量 的大小。倍数越大的，增长率必然越大。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "2. 排序增长“量”：", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 严格执行两步秒杀法：先看“大大则大”（现期大且增速大的排最前），再遇“一大一小”时比较 现期量×增速 的乘积。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[阅读题干, 用笔圈出是排'率'还是'量'] --> B{排什么?}\nB -- 率 --> C[直接计算 现期/基期 的商, 或利用百化分转换比较]\nB -- 量 --> D[利用'大大则大'法则找出领头羊和吊车尾]\nD --> E[遇到中间胶着项, 估算 现期×增速 乘积]\nC --> F[得出最终排序验证选项]\nE --> F"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 按降幅从大到小排序：甲(-15%), 乙(-8%), 丙(-20%)。正确的是？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "明确定义：降幅 = 减少的比率的绝对值。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "取绝对值：甲=15%，乙=8%，丙=20%。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "排大小：20% > 15% > 8%。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "锁定答案：丙 > 甲 > 乙。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "降幅排序陷阱：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "如果题目问“按增速从大到小排序”，那是看带负号的真实值：乙(-8%) > 甲(-15%) > 丙(-20%)。如果问“降幅”，降幅看绝对值！一字之差，答案完全相反！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "遇到含“增”字的排序题，拿红笔把后面紧跟的字圈出来。如果是“长”（增长量），画个绝对量的符号；如果是“速/幅”（增长率/降幅），画个 % 符号提醒自己。"}]}]}$$ AS jsonb), NULL, '增长类排序的核心考点与实战推导。', category_node.id, CAST('["资料分析", "增长类排序"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_rank_growth", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
